#!/usr/bin/env node
import { tryFastPath } from "axi-sdk-js/fast-path";
import { VERSION } from "../src/version.js";
if (!tryFastPath(process.argv.slice(2), { version: VERSION })) {
    const { main } = await import("../src/cli.js");
---
chrome-devtools
chrome-devtools-axi
chrome-devtools-mcp

arguments.content:
:root {
  --bg: #ffffff;
  --panel: rgba(20, 20, 25, 0.72);
  --text: #1c1c22;
  --accent: #4a90ff;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  overflow: hidden;
}

#scene {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

/* HUD overlay */
#hud {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 10;
  padding: 16px 18px;
  background: var(--panel);
  color: #fff;
  border-radius: 12px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.12);
  max-width: 260px;
  user-select: none;
}

#title {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

#subtitle {
  font-size: 12px;
  opacity: 0.7;
  margin-bottom: 14px;
  letter-spacing: 0.4px;
}

#controls {
  display: flex;
  flex-direction: column;
  gap: 9px;
  font-size: 13px;
}

#controls label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

#controls button {
  padding: 7px 10px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.15s ease;
}

#controls button:hover {
  background: #3a78e0;
}

#hint {
  margin-top: 12px;
  font-size: 11px;
  opacity: 0.55;
}

import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";

// =========================================================================
// SpaceX Raptor Engine — 3D viewer (three.js)
// White background theme; procedural geometry for all engine parts.
// =========================================================================

// ---- Global state (exposed for testing) ----
const state = {
  autoRotate: true,
  exhaustGlow: true,
  gimbalAngle: 0,
  parts: {}, // named groups for inspection
  fps: 0,
};
window.raptorState = state;

// ---- Renderer ----
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.outputColorSpace = THREE.SRGBColorSpace;

// ---- Scene & white background ----
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xffffff);

// ---- Camera ----
const camera = new THREE.PerspectiveCamera(
  45,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 8);

// ---- Controls ----
const controls = new OrbitControls(camera, canvas);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.minDistance = 3;
controls.maxDistance = 25;
controls.target.set(0, 2, 0);

// ---- Lighting (soft studio setup for a white theme) ----
function buildLighting() {
  const ambient = new THREE.AmbientLight(0xffffff, 0.55);
  scene.add(ambient);

  const key = new THREE.DirectionalLight(0xffffff, 2.4);
  key.position.set(6, 10, 6);
  key.castShadow = true;
  key.shadow.mapSize.set(2048, 2048);
  key.shadow.camera.near = 1;
  key.shadow.camera.far = 40;
  key.shadow.camera.left = -10;
  key.shadow.camera.right = 10;
  key.shadow.camera.top = 10;
  key.shadow.camera.bottom = -10;
  key.shadow.bias = -0.0004;
  scene.add(key);

  const fill = new THREE.DirectionalLight(0xbfd4ff, 0.9);
  fill.position.set(-7, 5, -4);
  scene.add(fill);

  const rim = new THREE.DirectionalLight(0xffffff, 0.7);
  rim.position.set(-2, 3, -8);
  scene.add(rim);

  const hemi = new THREE.HemisphereLight(0xffffff, 0xdedede, 0.6);
  scene.add(hemi);
}

// ---- Materials ----
function buildMaterials() {
  const steel = new THREE.MeshStandardMaterial({
    color: 0xbfc2c8,
    metalness: 0.85,
    roughness: 0.35,
  });
  const darkSteel = new THREE.MeshStandardMaterial({
    color: 0x3a3d44,
    metalness: 0.9,
    roughness: 0.4,
  });
  const nozzle = new THREE.MeshStandardMaterial({
    color: 0x2b2c30,
    metalness: 0.7,
    roughness: 0.5,
    side: THREE.DoubleSide,
  });
  const copper = new THREE.MeshStandardMaterial({
    color: 0xb87333,
    metalness: 0.85,
    roughness: 0.3,
  });
  const glow = new THREE.MeshBasicMaterial({
    color: 0xff6a3d,
    transparent: true,
    opacity: 0.0,
  });
  return { steel, darkSteel, nozzle, copper, glow };
}

// ---- Engine assembly ----
let engineGroup;
let exhaustMesh;
let gimbalGroup;
let materials;

function buildEngine() {
  engineGroup = new THREE.Group();
  materials = buildMaterials();

  // TODO: add sub-assemblies (nozzle, turbopump, head, gimbal, lines)
  buildNozzle();
  buildEngineHead();
  buildTurbopump();
  buildGimbal();
  buildPiping();

  engineGroup.position.set(0, 0, 0);
  scene.add(engineGroup);
  state.parts.engine = engineGroup;
}

function buildNozzle() {
  // TODO: main nozzle bell via LatheGeometry
}

function buildEngineHead() {
  // TODO: engine head / valve block assembly
}

function buildTurbopump() {
  // TODO: turbopump housing + preburner
}

function buildGimbal() {
  // TODO: gimbal ring mount at the base
}

function buildPiping() {
  // TODO: propellant/coolant lines
}

// ---- Exhaust glow sprite ----
function buildExhaust() {
  // TODO: additive glow disc at nozzle exit
}

// ---- Resize handling ----
function onResize() {
  // TODO: update camera aspect + renderer size
}

// ---- UI wiring ----
function bindUI() {
  // TODO: wire checkboxes / buttons to state
}

// ---- Animation loop ----
function animate() {
  requestAnimationFrame(animate);
  // TODO: rotate engine, update controls, exhaust flicker
  controls.update();
  renderer.render(scene, camera);
}

// ---- Init ----
function init() {
  buildLighting();
  buildEngine();
  buildExhaust();
  bindUI();
  window.addEventListener("resize", onResize);
  animate();
}

init();

