// In-page self-test: asserts the viewer's core behaviours with scripted
// inputs, prints a single PASS/FAIL summary, and returns the result.
// (Removed after verification, per run rules.)
function __selfTest() {
  const results = [];
  const add = (name, ok) => results.push({ name, ok });

  const parts = window.raptorState.parts;
  const expectedParts = ["nozzle", "head", "turbopump", "gimbal", "piping", "engine", "exhaust"];
  add("all engine parts present", expectedParts.every((p) => parts[p]));
  add("engine has geometry children", parts.engine.children.length > 0);
  add("exhaust mesh has opacity material", !!parts.exhaust && typeof parts.exhaust.material.opacity === "number");
  add("renderer clear color is white", window.__scene.scene.background.getHex() === 0xffffff);

  // Scripted input: engage gimbal -> rotation.x should move toward target.
  const gBefore = parts.engine.rotation.x;
  window.raptorState.gimbalAngle = 0.28;
  frame(1000);
  const gAfter = parts.engine.rotation.x;
  add("gimbal toggle rotates engine", Math.abs(gAfter - 0.28) < Math.abs(gBefore - 0.28) && Math.abs(gAfter) > 1e-3);

  // Scripted input: disable exhaust -> opacity should decay toward 0.
  parts.exhaust.material.opacity = 0.7; // deterministic starting value
  window.raptorState.exhaustGlow = false;
  for (let i = 0; i < 60; i++) frame(1000 + i);
  add("exhaust off decays opacity", parts.exhaust.material.opacity < 0.01);

  // Scripted input: enable exhaust -> opacity should rise.
  parts.exhaust.material.opacity = 0.0;
  window.raptorState.exhaustGlow = true;
  for (let i = 0; i < 60; i++) frame(5000 + i);
  add("exhaust on raises opacity", parts.exhaust.material.opacity > 0.3);

  // Reset scripted state.
  window.raptorState.gimbalAngle = 0;
  window.raptorState.exhaustGlow = true;
  frame(6000);

  const failed = results.filter((r) => !r.ok);
  console.log("SELF-TEST:", failed.length ? `FAIL (${failed.length}/${results.length})` : `PASS (${results.length}/${results.length})`);
  if (failed.length) console.table(results);
  return failed.length === 0;
}
window.__selfTest = __selfTest;

