:root {
  --bg: #ffffff;
  --panel: rgba(20, 20, 25, 0.72);
  --text: #1c1c22;
  --accent: #4a90ff;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  overflow: hidden;
}

#scene {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

/* HUD overlay */
#hud {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 10;
  padding: 16px 18px;
  background: var(--panel);
  color: #fff;
  border-radius: 12px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.12);
  max-width: 260px;
  user-select: none;
}

#title {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

#subtitle {
  font-size: 12px;
  opacity: 0.7;
  margin-bottom: 14px;
  letter-spacing: 0.4px;
}

#controls {
  display: flex;
  flex-direction: column;
  gap: 9px;
  font-size: 13px;
}

#controls label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

#controls button {
  padding: 7px 10px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.15s ease;
}

#controls button:hover {
  background: #3a78e0;
}

#hint {
  margin-top: 12px;
  font-size: 11px;
  opacity: 0.55;
}
